import java.util.*;
import java.io.*;

public class Main {
    static class Position {
        int row, col;
        Position(int r, int c) {
            this.row = r;
            this.col = c;
        }
    }

    static int[] delta_row = {-1, 0, 0, 1};
    static int[] delta_col = {0, -1, 1, 0};

    static int grid_size, time_limit;
    static char[][] grid = new char[12][12];
    static char[][] grid1 = new char[12][12];
    static char[][] grid2 = new char[12][12];
    static int[][] dist1 = new int[12][12];
    static int[][] dist2 = new int[12][12];

    static void compute_dist1(Position start) {
        for (int i = 0; i < 12; i++) {
            Arrays.fill(dist1[i], -1);
        }
        dist1[start.row][start.col] = 0;
        Queue<Position> q = new LinkedList<>();
        q.offer(start);
        while (!q.isEmpty()) {
            Position current = q.poll();
            for (int k = 0; k < 4; k++) {
                int nr = current.row + delta_row[k];
                int nc = current.col + delta_col[k];
                if (nr < 0 || nr >= grid_size + 2 || nc < 0 || nc >= grid_size + 2) continue;
                if (grid[nr][nc] != '.') continue;
                if (dist1[nr][nc] < 0) {
                    dist1[nr][nc] = dist1[current.row][current.col] + 1;
                    q.offer(new Position(nr, nc));
                }
            }
        }
    }

    static void compute_dist2(Position start) {
        for (int i = 0; i < 12; i++) {
            Arrays.fill(dist2[i], -1);
        }
        dist2[start.row][start.col] = 0;
        Queue<Position> q = new LinkedList<>();
        q.offer(start);
        while (!q.isEmpty()) {
            Position current = q.poll();
            if (dist1[current.row][current.col] >= 0 && dist2[current.row][current.col] >= dist1[current.row][current.col]) continue;
            for (int k = 0; k < 4; k++) {
                int nr = current.row + delta_row[k];
                int nc = current.col + delta_col[k];
                if (nr < 0 || nr >= grid_size + 2 || nc < 0 || nc >= grid_size + 2) continue;
                if (grid[nr][nc] != '.') continue;
                if (dist2[nr][nc] < 0) {
                    if (dist1[nr][nc] >= 0 && dist1[nr][nc] < dist2[current.row][current.col] + 1) continue;
                    dist2[nr][nc] = dist2[current.row][current.col] + 1;
                    q.offer(new Position(nr, nc));
                }
            }
        }
    }

    static class MaxFlow {
        int size;
        int[][] capacity;
        int[][] flow;
        int[] parent;
        int[] level;

        MaxFlow(int n) {
            size = n;
            capacity = new int[n][n];
            flow = new int[n][n];
            parent = new int[n];
            level = new int[n];
        }

        void add_edge(int u, int v, int cap) {
            capacity[u][v] += cap;
        }

        int bfs(int s, int t, List<Integer> path) {
            Arrays.fill(parent, -1);
            Arrays.fill(level, -1);
            level[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == t) {
                    int min_cap = Integer.MAX_VALUE;
                    for (int v = t; v != s; v = parent[v]) {
                        min_cap = Math.min(min_cap, capacity[parent[v]][v] - flow[parent[v]][v]);
                    }
                    path.clear();
                    for (int v = t; v != s; v = parent[v]) {
                        path.add(v);
                    }
                    path.add(s);
                    Collections.reverse(path);
                    return min_cap;
                }
                for (int v = 0; v < size; v++) {
                    if (parent[v] < 0 && capacity[u][v] - flow[u][v] > 0) {
                        parent[v] = u;
                        level[v] = level[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return 0;
        }

        int max_flow(int s, int t) {
            int total = 0;
            List<Integer> path = new ArrayList<>();
            int push;
            while ((push = bfs(s, t, path)) > 0) {
                for (int i = 0; i + 1 < path.size(); i++) {
                    int u = path.get(i);
                    int v = path.get(i + 1);
                    flow[u][v] += push;
                    flow[v][u] -= push;
                }
                total += push;
            }
            return total;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        grid_size = Integer.parseInt(st.nextToken());
        time_limit = Integer.parseInt(st.nextToken());

        for (int i = 0; i < 12; i++) {
            Arrays.fill(grid1[i], '#');
            Arrays.fill(grid2[i], '#');
            Arrays.fill(grid[i], '#');
        }

        List<Position> scientists = new ArrayList<>();
        List<Position> capsules = new ArrayList<>();
        Position z = new Position(0, 0);

        for (int r = 1; r <= grid_size; r++) {
            String line = br.readLine();
            for (int c = 1; c <= grid_size; c++) {
                grid1[r][c] = line.charAt(c - 1);
            }
            for (int c = 1; c <= grid_size; c++) {
                grid2[r][c] = line.charAt(c - 1);
            }
        }

        for (int r = 1; r <= grid_size; r++) {
            for (int c = 1; c <= grid_size; c++) {
                if (Character.isDigit(grid1[r][c])) {
                    if (grid1[r][c] > '0') {
                        scientists.add(new Position(r, c));
                    }
                    grid[r][c] = '.';
                } else if (grid1[r][c] == 'Z') {
                    z = new Position(r, c);
                    grid[r][c] = '.';
                }
                if (Character.isDigit(grid2[r][c]) && grid2[r][c] > '0') {
                    capsules.add(new Position(r, c));
                }
            }
        }

        compute_dist1(z);
        int source = 0;
        int sink = scientists.size() + capsules.size() + 1;
        MaxFlow mf = new MaxFlow(sink + 1);

        for (int i = 0; i < scientists.size(); i++) {
            int cap = grid1[scientists.get(i).row][scientists.get(i).col] - '0';
            mf.add_edge(source, i + 1, cap);
        }

        for (int j = 0; j < capsules.size(); j++) {
            int cap = grid2[capsules.get(j).row][capsules.get(j).col] - '0';
            mf.add_edge(scientists.size() + j + 1, sink, cap);
        }

        for (int i = 0; i < scientists.size(); i++) {
            compute_dist2(scientists.get(i));
            for (int j = 0; j < capsules.size(); j++) {
                int dist = dist2[capsules.get(j).row][capsules.get(j).col];
                if (dist >= 0 && dist <= time_limit) {
                    mf.add_edge(i + 1, scientists.size() + j + 1, Integer.MAX_VALUE);
                }
            }
        }

        int result = mf.max_flow(source, sink);
        System.out.println(result);
    }
}
